// src/components/Admin/Kitchen.js
import React, { useEffect, useState } from 'react';
import './Kitchen.css';

function getCardVariant(order) {
  if (order.status === 'processing') return 'processing';
  if (order.status === 'done' && order.type === 'Dine In') return 'done-dinein';
  if (order.status === 'done' && order.type !== 'Dine In') return 'done-takeaway';
  return 'processing';
}

// Compute remaining minutes safely from startedAt + durationMinutes
function getRemainingMinutes(order) {
  // Fallbacks for older orders that may not have the new timing fields
  const total =
    typeof order.durationMinutes === 'number'
      ? order.durationMinutes
      : (() => {
          const m = /\d+/.exec(order.duration || '');
          return m ? parseInt(m[0], 10) : 15;
        })();

  const startedMs = order.startedAt ? Number(order.startedAt) : Date.now();
  const elapsedMin = Math.floor((Date.now() - startedMs) / 60000);
  const remain = Math.max(0, total - elapsedMin);
  return remain;
}

function StatusPill({ order, tick }) {
  // re-compute when global tick changes
  const isProcessing = order.status === 'processing';
  const isDineIn = order.type === 'Dine In';

  let title = '';
  let sub = '';

  if (isProcessing) {
    const left = getRemainingMinutes(order); // live minutes
    title = isDineIn ? 'Dine In' : 'Take Away';
    sub = `Ongoing: ${left} Min`;
  } else {
    if (isDineIn) {
      title = 'Done';
      sub = 'Served';
    } else {
      title = 'Take Away';
      sub = 'Not Picked up';
    }
  }

  return (
    <div className="status-pill">
      <div>{title}</div>
      <div className="small">{sub}</div>
    </div>
  );
}

function OrderCard({ order, onComplete, tick }) {
  const variant = getCardVariant(order);
  const isProcessing = order.status === 'processing';
  const isDineIn = order.type === 'Dine In';

  return (
    <div className={`order-card ${variant}`}>
      <div className="card-head">
        <div className="head-left">
          <div className="head-icon" aria-hidden>
            <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
              <path d="M7 2c.55 0 1 .45 1 1v7h1V3a1 1 0 1 1 2 0v7h1V3a1 1 0 1 1 2 0v8a3 3 0 0 1-3 3h-1v7a1 1 0 1 1-2 0v-7H9a3 3 0 0 1-3-3V3c0-.55.45-1 1-1zM17 2h2v20a1 1 0 1 1-2 0V2z"/>
            </svg>
          </div>
          <div>
            <div className="order-id">#{order.id}</div>
            <div className="order-meta">
              <span>{isDineIn ? order.table : 'Takeaway'}</span>
              <span>{order.time}</span>
              <span>{order.itemCount} Item</span>
            </div>
          </div>
        </div>
        <StatusPill order={order} tick={tick} />
      </div>

      <div className="order-card__body">
        <div className="items-block">
          {(order.items || []).map((it, idx) => (
            <div className="item-row" key={idx}>
              <span className="item-qty">{it.quantity} x</span>
              <span className="item-name">{it.name}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="card-foot">
        {isProcessing ? (
          <button className="action-btn" onClick={() => onComplete(order.id)}>
            Processing <span className="btn-icon">⏳</span>
          </button>
        ) : (
          <button className="action-btn" type="button">
            Order Done <span className="btn-icon">✅</span>
          </button>
        )}
      </div>
    </div>
  );
}

export default function Kitchen({ orders = [], updateOrderStatus }) {
  // tick forces a re-render to update timers
  const [tick, setTick] = useState(0);

  useEffect(() => {
    // update every 30 seconds (change to 60*1000 for per-minute)
    const id = setInterval(() => setTick(t => t + 1), 30000);
    return () => clearInterval(id);
  }, []);

  const sorted = [...orders].sort((a, b) => {
    if (a.status === b.status) return b.id - a.id;
    return a.status === 'processing' ? -1 : 1;
  });

  const handleCompleteOrder = (orderId) => {
    updateOrderStatus(orderId, 'done');
  };

  return (
    <div className="kitchen-container">
      <h1 className="kitchen-title">Order Line</h1>
      <div className="orders-grid">
        {sorted.length === 0 ? (
          <p>No orders yet.</p>
        ) : (
          sorted.map(o => (
            <OrderCard key={o.id} order={o} onComplete={handleCompleteOrder} tick={tick} />
          ))
        )}
      </div>
    </div>
  );
}
